-- Skins da Bíblia: uma por livro, sem preço. O app libera cada skin no próprio aparelho quando a pessoa
-- conclui o livro (a posse viaja na carteira do progresso). Estas linhas existem para o servidor reconhecer
-- a skin equipada (ranking e perfis usam public.social_skin, que só aceita skins oficiais e ativas).
--
-- A regra de liberação é {"kind":"book"}, que purchase_lumi_item não conhece: o servidor NÃO vende estas skins
-- (retorna 'unsupported-unlock-rule'). As cinco skins antigas (Gênesis a Deuteronômio) não são alteradas aqui.
-- Aditiva e idempotente: pode ser reaplicada.
begin;

on conflict(id) do update set name=excluded.name,description=excluded.description,category=excluded.category,price=excluded.price,rarity=excluded.rarity,asset_path=excluded.asset_path,asset_status=excluded.asset_status,unlock_rule=excluded.unlock_rule,layer_order=excluded.layer_order,anchor=excluded.anchor,active=excluded.active,updated_at=now();

notify pgrst, 'reload schema';
commit;
